import json
import os
from dataclasses import dataclass, field


@dataclass
class Interface:
    name: str
    vlan: int | None = None
    enabled: bool = True
    description: str = ""
    tagged: list[int] = field(default_factory=list)


def parse_vlan_list(spec: str) -> list[int]:
    vlans = []
    parts = spec.split()
    i = 0
    while i < len(parts):
        if i + 2 < len(parts) and parts[i + 1] == "to":
            start, end = int(parts[i]), int(parts[i + 2])
            print("range", start, end)
            vlans.extend(range(start, end + 1))
            i += 3
        else:
            print("single", parts[i])
            vlans.append(int(parts[i]))
            i += 1
    return vlans


def load_inventory(path: str) -> dict[str, list[Interface]]:
    if not os.path.exists(path):
        print("inventory not found:", path)
        return {}
    with open(path, encoding="utf-8") as fh:
        raw = json.load(fh)
    devices = {}
    for device, items in raw.items():
        print("loading", device, len(items))
        devices[device] = [Interface(**item) for item in items]
    return devices


def disabled_interfaces(devices: dict[str, list[Interface]]) -> list[tuple[str, str]]:
    result = []
    for device, interfaces in devices.items():
        for iface in interfaces:
            if not iface.enabled:
                print("disabled", device, iface.name)
                result.append((device, iface.name))
    return result


def trunk_report(devices: dict[str, list[Interface]]) -> str:
    lines = []
    for device, interfaces in sorted(devices.items()):
        for iface in interfaces:
            if iface.tagged:
                lines.append(f"{device} {iface.name} {','.join(map(str, iface.tagged))}")
    print("trunks", len(lines))
    return "\n".join(lines)


if __name__ == "__main__":
    inventory = load_inventory("inventory.json")
    print(disabled_interfaces(inventory))
    print(trunk_report(inventory))
